SELECT exam_batch_id, exam_name, exam_date, school_id, school_name, district, subject, min_full_score, max_full_score, min_pass_score, max_pass_score, recorded_count, valid_count, missing_score_count, total_valid_score, average_score, pass_count, pass_rate_denominator, unclassified_score_count, pass_rate FROM exam_school_subject_summary WHERE exam_batch_id = 2 ORDER BY school_name, subject